    pending_async_assist_operation_id: Any = None
    # Output only. The time the session started.
    start_time: Any = None
    # The state of the session.
    state: Any = None
    # Turns.
    turns: Any = None
    # A unique identifier for tracking users.
    user_pseudo_id: Any = None

